body:
It seems that the culprit is the immutable sampler (shadow sampler) in the mobile renderer, and I can fix the issue by changing it to not use immutable sampler. Not sure what the correct fix is, the message "Set 0 binding 0 pImmutableSamplers 0xdab6030 doesn't match 0xde199e0" is weird, because set 0 binding 0 isn't bound to anything.

```diff
diff --git a/servers/rendering/renderer_rd/forward_mobile/render_forward_mobile.cpp b/servers/rendering/renderer_rd/forward_mobile/render_forward_mobile.cpp
index 5106db267c..803e256455 100644
--- a/servers/rendering/renderer_rd/forward_mobile/render_forward_mobile.cpp
+++ b/servers/rendering/renderer_rd/forward_mobile/render_forward_mobile.cpp
@@ -1803,7 +1803,6 @@ void RenderForwardMobile::_update_render_base_uniform_set() {
 			u.binding = 2;
 			u.uniform_type = RD::UNIFORM_TYPE_SAMPLER;
 			u.append_id(scene_shader.shadow_sampler);
-			u.immutable_sampler = true;
 			uniforms.push_back(u);
 		}

diff --git a/servers/rendering/renderer_rd/forward_mobile/scene_shader_forward_mobile.cpp b/servers/rendering/renderer_rd/forward_mobile/scene_shader_forward_mobile.cpp
index cc0f406b6d..07841b2e8f 100644
--- a/servers/rendering/renderer_rd/forward_mobile/scene_shader_forward_mobile.cpp
+++ b/servers/rendering/renderer_rd/forward_mobile/scene_shader_forward_mobile.cpp
@@ -559,7 +559,6 @@ void SceneShaderForwardMobile::init(const String p_defines) {
 	// Store whether the shader will prefer using the FP16 variant.
 	use_fp16 = RD::get_singleton()->has_feature(RD::SUPPORTS_HALF_FLOAT);

-	// Immutable samplers : create the shadow sampler to be passed when creating the pipeline.
 	{
 		RD::SamplerState sampler;
 		sampler.mag_filter = RD::SAMPLER_FILTER_LINEAR;
@@ -595,13 +594,7 @@ void SceneShaderForwardMobile::init(const String p_defines) {
 			}
 		}

-		Vector<RD::PipelineImmutableSampler> immutable_samplers;
-		RD::PipelineImmutableSampler immutable_shadow_sampler;
-		immutable_shadow_sampler.binding = 2;
-		immutable_shadow_sampler.append_id(shadow_sampler);
-		immutable_shadow_sampler.uniform_type = RenderingDeviceCommons::UNIFORM_TYPE_SAMPLER;
-		immutable_samplers.push_back(immutable_shadow_sampler);
-		shader.initialize(shader_versions, p_defines, immutable_samplers);
+		shader.initialize(shader_versions, p_defines);

 		if (RendererCompositorRD::get_singleton()->is_xr_enabled()) {
 			enable_multiview_shader_group();

```

I think the core issue around this is if you are actually allowed to go

```c++
VkSamplerCreateInfo ci
vkCreateSample(ci, &sampler_0);
vkCreateSample(ci, &sampler_1);

vkCreatePipelineLayout(pImmutableSamplers = sampler_0, &pipe_layout_0);
vkCreatePipelineLayout(pImmutableSamplers = sampler_1, &pipe_layout_1);

vkCmdBindPipeline(pipeline); // layout_0
vkCmdBindDescriptorSets(pipe_layout_1);
vkCmdDraw();
```

Seems like the Validation Layers checks if the pImmutableSamplers pointer were the same (which is for sure wrong and fixing!!) but the next question is if the `VkSampler` needs to be the same handle or not, and getting 100% clarification in 
https://github.com/KhronosGroup/Vulkan-Docs/issues/164#issuecomment-3198346327
